        /// <summary>
        /// Zero-alloc LNLQ (Estrin, Orban &amp; Saunders 2019) solver for UNDERDETERMINED consistent
        /// systems: among all x with A x = b, finds the one of minimum Euclidean norm,
        /// x* = Aᵀ(AAᵀ)⁻¹b, generic over <see cref="IdoubleLinearOperator"/>. Builds the same
        /// Golub-Kahan bidiagonalization as <see cref="craig{TOp}"/> and returns the SAME min-norm
        /// iterate (LNLQ's transferred CRAIG point, x^C in the reference), but folds it through an LQ
        /// factorization -- the SYMMLQ-equivalent formulation on the normal equations of the second
        /// kind (A Aᵀ y = b, x = Aᵀ y). Requires A (Rows ≤ Cols) full row rank and b ∈ range(A). O(n+m)
        /// memory and per-iteration cost (1 Apply + 1 ApplyT).
        ///
        /// No warm start: the min-norm characterization only holds from x₀ = 0, so x is zeroed
        /// internally. Converges when ‖b-Ax‖ &lt;= tol*‖b‖. Returns an <see cref="LnlqInfo"/>;
        /// rnorm/xnorm are certified-exact (one extra Apply + ApplyT), and a claimed Converged is
        /// reconciled against that certified rnorm before being reported. Breakdown when the
        /// bidiagonalization collapses before ‖b-Ax‖ reaches tolerance (A lacks full row rank, or b
        /// ∉ range(A) on the first step).
        ///
        /// <see cref="LnlqInfo.xErrBound"/> is <see cref="double.NaN"/> on these overloads: the
        /// certified Gauss-Radau forward-error bound is supplied only by the overloads that take a
        /// σ_min underestimate.
        /// </summary>
        public static LnlqInfo lnlq<TOp>(in TOp A, in doubleN b, ref doubleN x,
                                     ref doubleN u, ref doubleN v,
                                     ref doubleN tmpM, ref doubleN tmpN,
                                     int maxIter, double tol)
            where TOp : struct, IdoubleLinearOperator
        {
            if (A.Rows > A.Cols) throw new ArgumentException("lnlq: A must be square or underdetermined (Rows <= Cols)");
            if (b.N != A.Rows) throw new ArgumentException("lnlq: b.N must equal A.Rows");
            if (x.N != A.Cols) throw new ArgumentException("lnlq: x.N must equal A.Cols");
            if (u.N != A.Rows) throw new ArgumentException("lnlq: u.N must equal A.Rows");
            if (tmpM.N != A.Rows) throw new ArgumentException("lnlq: tmpM.N must equal A.Rows");
            if (v.N != A.Cols) throw new ArgumentException("lnlq: v.N must equal A.Cols");
            if (tmpN.N != A.Cols) throw new ArgumentException("lnlq: tmpN.N must equal A.Cols");

            if (maxIter < 1)
                throw new ArgumentException("lnlq: maxIter must be >= 1");

            unsafe
            {
                long* ptrs = stackalloc long[6];
                ptrs[0] = (long)u.Data.Ptr; ptrs[1] = (long)v.Data.Ptr;
                ptrs[2] = (long)tmpM.Data.Ptr; ptrs[3] = (long)tmpN.Data.Ptr;
                ptrs[4] = (long)x.Data.Ptr; ptrs[5] = (long)b.Data.Ptr;
                RequireDistinctBuffers("lnlq: u/v/tmpM/tmpN/x/b must be distinct", ptrs, 6);
            }

            // No warm start: the min-norm characterization x = Aᵀ(AAᵀ)⁻¹b requires x₀ = 0.
            for (int i = 0; i < x.N; i++) x[i] = (double)0;

            double bnorm = math.sqrt(Blas.dot(b, b));
            if (bnorm == (double)0)
                // b = 0: the min-norm solution is trivially x = 0.
                return LnlqInfoFrom(IterativeSolveStatus.Converged, 0, in A, in b, ref x, ref tmpM, ref tmpN);

            // beta_1 u_1 = b  (Algorithm 1 line 1)
            u.CopyFrom(in b);
            u.divInPlace(bnorm);
            double beta = bnorm;

            // v_0 = 0 bootstraps the first bidiagonalization step: alpha_1 v_1 = Aᵀu_1 - beta_1·0.
            for (int j = 0; j < v.N; j++) v[j] = (double)0;
            // Dummy pre-loop value; the tau-recurrence below yields tau_1 = beta_1/alpha_1 on the first
            // iteration (the sign flip cancels the leading minus). tau_k == the reference's x^C step.
            double tau = (double)(-1);

            for (int k = 0; k < maxIter; k++)
            {
                // ---- Golub-Kahan: alpha_{k+1} v_{k+1} = Aᵀ u_{k+1} - beta_{k+1} v_k ----
                double alfa = GolubKahanVStep(in A, in u, beta, ref tmpN, ref v);

                if (!(alfa > (double)0)) // NaN-safe: alfa is a norm, nonnegative
                    // v collapsed: the Krylov space on AAᵀ is exhausted before reaching b -- A is not
                    // full row rank (or, on the first step, b ∉ range(A)).
                    return LnlqInfoFrom(IterativeSolveStatus.Breakdown, k + 1, in A, in b, ref x, ref tmpM, ref tmpN);

                v.divInPlace(alfa);

                // x^C update (Algorithm 2 lines 17-18): tau_{k+1} = -beta_{k+1} tau_k / alpha_{k+1};
                // x^C_{k+1} = x^C_k + tau_{k+1} v_{k+1}. Each v is an Aᵀ-image, so x stays in row(A).
                tau = -(beta / alfa) * tau;
                x.addScaledInPlace(tau, v);

                // beta_{k+1} u_{k+1} = A v_k - alpha_k u_k.
                beta = GolubKahanUStep(in A, in v, alfa, ref tmpM, ref u);

                // ‖b - A x‖ from the same recurrence (Paige-Saunders) -- no extra matvec.
                double rnorm = math.abs(beta * tau);

                if (rnorm <= tol * bnorm)
                {
                    // Verify-at-exit: the tracked estimate can drift on an ill-conditioned A. LnlqInfoFrom
                    // pays for a certified-exact ‖b-Ax‖ audit for every exit; only commit to Converged if
                    // that certified residual also clears the threshold (else fall through).
                    var info = LnlqInfoFrom(IterativeSolveStatus.Converged, k + 1, in A, in b, ref x, ref tmpM, ref tmpN);
                    if (info.rnorm <= tol * bnorm)
                        return info;
                }

                if (!(beta > (double)0)) // NaN-safe: beta is a norm, nonnegative
                    return LnlqInfoFrom(IterativeSolveStatus.Breakdown, k + 1, in A, in b, ref x, ref tmpM, ref tmpN);

                u.divInPlace(beta);
            }

            return LnlqInfoFrom(IterativeSolveStatus.MaxIterations, maxIter, in A, in b, ref x, ref tmpM, ref tmpN);
        }

        /// <summary>Assembles the returned <see cref="LnlqInfo"/> from a certified-exact residual audit
        /// (<see cref="lstsqResidual{TOp}"/>: one Apply + one ApplyT). xErrBound is NaN -- the
